import SwiftUI
import WidgetKit

// MARK: - Jokes

struct Joke: Codable {
    let setup: String
    let punch: String
}

enum JokeLibrary {
    /// Bundled copy of the app's jokes (generated by scripts/build_widget_jokes.js).
    static let all: [Joke] = {
        guard let url = Bundle.main.url(forResource: "jokes", withExtension: "json"),
              let data = try? Data(contentsOf: url),
              let jokes = try? JSONDecoder().decode([Joke].self, from: data),
              !jokes.isEmpty
        else {
            return [Joke(setup: "I'm reading a book about anti-gravity.", punch: "It's impossible to put down.")]
        }
        return jokes
    }()

    /// The same joke all day, a different one each day.
    static func joke(for date: Date) -> Joke {
        let day = Calendar.current.ordinality(of: .day, in: .era, for: date) ?? 0
        return all[(day &* 7919) % all.count]
    }
}

// MARK: - Timeline

struct JokeEntry: TimelineEntry {
    let date: Date
    let joke: Joke
}

struct Provider: TimelineProvider {
    func placeholder(in context: Context) -> JokeEntry {
        JokeEntry(date: Date(), joke: JokeLibrary.joke(for: Date()))
    }

    func getSnapshot(in context: Context, completion: @escaping (JokeEntry) -> Void) {
        completion(placeholder(in: context))
    }

    func getTimeline(in context: Context, completion: @escaping (Timeline<JokeEntry>) -> Void) {
        let calendar = Calendar.current
        let today = calendar.startOfDay(for: Date())
        var entries = [JokeEntry(date: Date(), joke: JokeLibrary.joke(for: today))]
        for offset in 1..<7 {
            if let day = calendar.date(byAdding: .day, value: offset, to: today) {
                entries.append(JokeEntry(date: day, joke: JokeLibrary.joke(for: day)))
            }
        }
        completion(Timeline(entries: entries, policy: .atEnd))
    }
}

// MARK: - Views

private enum Palette {
    static let background = Color(red: 0.043, green: 0.043, blue: 0.047)
    static let ink = Color(red: 0.957, green: 0.937, blue: 0.902)
    static let gold = Color(red: 0.910, green: 0.725, blue: 0.290)
    static let muted = Color(red: 0.541, green: 0.522, blue: 0.486)
}

struct DadJokesWidgetView: View {
    @Environment(\.widgetFamily) private var family
    let entry: JokeEntry

    var body: some View {
        content.widgetBackground(Palette.background)
    }

    @ViewBuilder private var content: some View {
        if isLockScreen {
            VStack(alignment: .leading, spacing: 2) {
                Text("DAD JOKE").font(.system(size: 11, weight: .bold))
                Text(entry.joke.setup)
                    .font(.system(size: 14, weight: .semibold, design: .serif))
                    .lineLimit(3)
                    .minimumScaleFactor(0.7)
            }
            .frame(maxWidth: .infinity, alignment: .leading)
        } else if family == .systemSmall {
            VStack(alignment: .leading, spacing: 0) {
                header
                Spacer(minLength: 6)
                setupText(size: 17, lines: 5)
            }
            .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .topLeading)
        } else {
            VStack(alignment: .leading, spacing: 0) {
                header
                Spacer(minLength: 8)
                setupText(size: family == .systemLarge ? 30 : 19, lines: family == .systemLarge ? 6 : 3)
                HStack(alignment: .top, spacing: 10) {
                    Rectangle().fill(Palette.gold).frame(width: 2)
                    Text(entry.joke.punch)
                        .font(.system(size: family == .systemLarge ? 22 : 15, weight: .regular, design: .serif))
                        .italic()
                        .foregroundColor(Palette.gold)
                        .lineLimit(family == .systemLarge ? 4 : 2)
                        .minimumScaleFactor(0.7)
                }
                .fixedSize(horizontal: false, vertical: true)
                .padding(.top, family == .systemLarge ? 16 : 8)
            }
            .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .topLeading)
        }
    }

    private var isLockScreen: Bool {
        if #available(iOSApplicationExtension 16.0, *) {
            return family == .accessoryRectangular
        }
        return false
    }

    private var header: some View {
        HStack(spacing: 0) {
            Text("DAD").font(.system(size: 12, weight: .black)).kerning(2).foregroundColor(Palette.ink)
            Text(".").font(.system(size: 12, weight: .black)).foregroundColor(Palette.gold)
        }
    }

    private func setupText(size: CGFloat, lines: Int) -> some View {
        Text(entry.joke.setup)
            .font(.system(size: size, weight: .heavy, design: .serif))
            .foregroundColor(Palette.ink)
            .lineLimit(lines)
            .minimumScaleFactor(0.6)
    }
}

extension View {
    /// iOS 17+ widgets need containerBackground; older versions need explicit padding.
    @ViewBuilder func widgetBackground(_ color: Color) -> some View {
        if #available(iOSApplicationExtension 17.0, *) {
            containerBackground(color, for: .widget)
        } else {
            padding().background(color)
        }
    }
}

// MARK: - Widget

@main
struct DadJokesWidget: Widget {
    let kind = "DadJokesWidget"

    var body: some WidgetConfiguration {
        StaticConfiguration(kind: kind, provider: Provider()) { entry in
            DadJokesWidgetView(entry: entry)
        }
        .configurationDisplayName("Daily Dad Joke")
        .description("A fresh groaner on your Home Screen every day.")
        .supportedFamilies(families)
    }

    private var families: [WidgetFamily] {
        if #available(iOSApplicationExtension 16.0, *) {
            return [.systemSmall, .systemMedium, .systemLarge, .accessoryRectangular]
        }
        return [.systemSmall, .systemMedium, .systemLarge]
    }
}
